reference_solution.javascript:
function findKthLargest(nums, k) {
    const heap = new MinHeap();
    for (const n of nums) {
        heap.push(n);
        if (heap.size() > k) heap.pop();
    }
    return heap.peek();
}
class MinHeap {
    constructor() { this.heap = []; }
    push(val) { this.heap.push(val); this._bubbleUp(); }
    pop() { const min = this.heap[0]; const end = this.heap.pop(); if (this.heap.length > 0) { this.heap[0] = end; this._sinkDown(); } return min; }
    peek() { return this.heap[0]; }
    size() { return this.heap.length; }
    _bubbleUp() { let idx = this.heap.length-1; while (idx > 0) { const parent = Math.floor((idx-1)/2); if (this.heap[parent] <= this.heap[idx]) break; [this.heap[parent], this.heap[idx]] = [this.heap[idx], this.heap[parent]]; idx = parent; } }
    _sinkDown() { let idx = 0; while (true) { let smallest = idx; const left = 2*idx+1, right = 2*idx+2; if (left < this.heap.length && this.heap[left] < this.heap[smallest]) smallest = left; if (right < this.heap.length && this.heap[right] < this.heap[smallest]) smallest = right; if (smallest === idx) break; [this.heap[smallest], this.heap[idx]] = [this.heap[idx], this.heap[smallest]]; idx = smallest; } }
}
